#![allow(clippy::excessive_precision)]

use thermopack_rs::{Unifac, UnifacVariant};

/// The source reports the excess Gibbs energy per kilomole; its gas constant
/// is 1000*R. The native model works per mole.
const SOURCE_UNIT_SCALE: f64 = 1000.0;

fn variant(label: &str) -> UnifacVariant {
    match label {
        "UNIFAC" => UnifacVariant::Unifac,
        "UMR" => UnifacVariant::Umr,
        "VTPR" => UnifacVariant::Vtpr,
        other => panic!("unknown unifac variant: {other}"),
    }
}

fn native_values(model: &Unifac, temperature: f64, composition: &[f64]) -> Vec<f64> {
    let result = model.excess_gibbs(temperature, composition).unwrap();
    let mut values = vec![result.gibbs, result.dg_dt, result.d2g_dt2];
    values.extend(result.dg_dn.iter().copied());
    values.extend(result.d2g_dn_dt.iter().copied());
    values.extend(result.d2g_dn_dn.iter().copied());
    values
}

#[test]
fn unifac_excess_gibbs_matches_the_source() {
    let mut checked = 0;
    for row in include_str!("fixtures/unifac.csv").lines().skip(1) {
        let fields: Vec<_> = row.split(';').collect();
        let case = fields[0];
        let parts: Vec<_> = case.split('|').collect();
        let components: Vec<&str> = parts[1].split(',').collect();
        let temperature: f64 = parts[2].parse().unwrap();
        let composition: Vec<f64> = parts[3].split(',').map(|v| v.parse().unwrap()).collect();
        let model = Unifac::new(&components, variant(parts[4])).unwrap();
        let actual = native_values(&model, temperature, &composition);
        let expected: Vec<f64> = fields[1..].iter().map(|v| v.parse().unwrap()).collect();
        assert_eq!(expected.len(), actual.len(), "{case}");
        for (position, (source, native)) in expected.iter().zip(actual.iter()).enumerate() {
            let scaled = native * SOURCE_UNIT_SCALE;
            let tolerance = 1e-6 + 1e-10 * source.abs().max(scaled.abs());
            assert!(
                (source - scaled).abs() <= tolerance,
                "{case} quantity {position}: source {source} native {scaled}"
            );
        }
        checked += 1;
    }
    assert_eq!(checked, 1540);
}

#[test]
fn unifac_source_status_is_reproduced() {
    let mut statuses = [0usize; 4];
    for row in include_str!("fixtures/unifac_status.csv").lines().skip(1) {
        let (case, status) = row.split_once(';').unwrap();
        let status: usize = status.parse().unwrap();
        let parts: Vec<_> = case.split('|').collect();
        let components: Vec<&str> = parts[1].split(',').collect();
        let model = Unifac::new(&components, variant(parts[4]));
        let terminated = model.is_err();
        assert_eq!(terminated, status == 1, "{case}");
        statuses[status] += 1;
    }
    assert_eq!(statuses[1], 0);
    assert_eq!(statuses[2], 0);
    assert_eq!(statuses[3], 0);
    assert_eq!(statuses[0], 1540);
}

#[test]
fn unifac_group_database_is_complete() {
    // Every source component must be resolvable and produce a usable
    // parameter set.
    let components = [
        "C2", "C3", "IC4", "NC4", "NC5", "IC5", "NC6", "NC7", "NC8", "NC9", "NC10", "NC11",
        "BENZENE", "H2O", "N2", "CO2", "H2S", "C1", "ACETONE",
    ];
    for identifier in components {
        let model = Unifac::new(&[identifier], UnifacVariant::Unifac).unwrap();
        assert_eq!(model.nc, 1);
        assert!(model.ng >= 1);
    }
    // The source database spells the toluene identifier "TOLUENE" while the
    // equation of state uses "TOLU", so the lookup must fail as it does in
    // the original.
    assert!(Unifac::new(&["TOLU"], UnifacVariant::Unifac).is_err());
    assert!(Unifac::new(&["TOLUENE"], UnifacVariant::Unifac).is_ok());
    assert!(Unifac::new(&["NOT_A_COMPONENT"], UnifacVariant::Unifac).is_err());
}
